window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["knowledge-graph"]={"title":"知识图谱：把身份、关系、时间与证据组织成可查询事实","subtitle":"从本体、实体解析和时态边，到路径检索与 GraphRAG，理解图何时优于相似度、又怎样传播错误。","thesis":"知识图谱不是“节点连线图”，而是对实体身份、关系语义、有效时间和证据来源的显式契约；多跳能力的上限首先受<b>实体解析与边的可追溯性</b>约束。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"Apple 收购 Beats；Tim 领导 Apple","rule":"先给 Apple 公司分配","steps":"0.9×0.95^3≈0.772","interpretation":"最终必须回查三段原文"}}],"formulas":[{"id":"knowledge-graph-fact","section":2,"formulaIndex":1,"symbols":[{"name":"Fact","meaning":"一条带限定条件和治理状态的图事实","evidence":"输出一条可追踪、可撤回的限定边 Fact"},{"name":"subject","meaning":"事实的主体稳定实体 ID","evidence":"主体 subject"},{"name":"predicate","meaning":"受控本体中的关系类型","evidence":"关系 predicate"},{"name":"object","meaning":"事实的客体实体或值","evidence":"客体 object"},{"name":"validTime","meaning":"事实成立的有效时间","evidence":"有效时间 validTime"},{"name":"source","meaning":"支持事实的原文证据","evidence":"来源 source"},{"name":"confidence","meaning":"抽取或确认置信信息","evidence":"置信度 confidence"},{"name":"status","meaning":"候选确认冲突或撤回状态","evidence":"状态 status"}]},{"id":"knowledge-graph-path-confidence","section":3,"formulaIndex":1,"symbols":[{"name":"Ppath","meaning":"独立近似下整条路径的正确概率","evidence":"输出 cook 到 dre 的可追踪路径及独立近似置信度 Ppath"},{"name":"pEntity","meaning":"锚点实体解析正确率","evidence":"实体解析正确率 pEntity"},{"name":"pEdge","meaning":"每一条关系边的正确率","evidence":"每条边正确率 pEdge"},{"name":"h","meaning":"路径包含的关系边数量","evidence":"路径边数 h"}]}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"知识图谱用稳定实体和显式关系组织可追踪事实。","evidence":"图解决的是关系寻址，而不只是相似搜索"},"problem":{"answer":"它解决唯一身份、多跳约束、时间版本和全局结构查询。","evidence":"向量检索能找到相关段落，为什么还要图"},"inputOutput":{"answer":"输入实体关系时间证据，输出可按关系查询的事实图。","evidence":"输出可按关系和约束查询的事实图"},"mechanism":{"answer":"把实体身份和受控边显式存储后按路径寻址。","evidence":"擅长唯一身份、多跳、时间版本与全局结构"},"interpretation":{"answer":"路径存在只说明图中有连接，不说明连接真实。","evidence":"不表示连接真实"},"boundary":{"answer":"单段可答或维护收益不足时无需建设知识图谱。","evidence":"单段即可回答或维护成本高于收益时不必建图"}},{"section":2,"definition":{"answer":"图事实是带身份、关系、时间、来源、置信和状态的边。","evidence":"事实应是带限定条件的边"},"problem":{"answer":"它避免把带历史与冲突的事实简化为三个字符串。","evidence":"为什么不是三个字符串就够"},"inputOutput":{"answer":"输入七类限定字段，输出可追踪可撤回事实边。","evidence":"输出一条可追踪、可撤回的限定边 Fact"},"mechanism":{"answer":"稳定 ID 定身份，本体定关系，时间来源定适用证据。","evidence":"稳定 ID 区分同名实体"},"interpretation":{"answer":"时间与来源说明事实何时成立以及凭什么成立。","evidence":"时间和来源限定事实何时及为何成立"},"boundary":{"answer":"缺限定字段的三元组不能可靠支持历史冲突查询。","evidence":"不能支持可靠历史与冲突查询"}},{"section":3,"definition":{"answer":"多跳查询沿受控关系从起点实体连接到目标实体。","evidence":"完整示例：从四句话解析同名实体并回答多跳问题"},"problem":{"answer":"它展示同名解析和每条边错误如何影响最终路径。","evidence":"怎样回答“Tim 间接关联谁”"},"inputOutput":{"answer":"输入实体和边正确率，输出路径及近似置信度。","evidence":"输出 cook 到 dre 的可追踪路径及独立近似置信度 Ppath"},"mechanism":{"answer":"先解析稳定实体，再按关系方向走三条边并乘正确率。","evidence":"Ppath=pEntity×pEdge^h"},"interpretation":{"answer":"零点七七二说明每一跳误差会累积降低路径可信度。","evidence":"说明每跳误差会累积"},"boundary":{"answer":"独立假设只作直觉，最终必须逐边回查原文。","evidence":"最终必须回查三段原文"}},{"section":4,"definition":{"answer":"本体是为目标问题定义实体关系方向基数和时间规则的最小约束。","evidence":"本体是问题驱动的约束"},"problem":{"answer":"它避免关系过宽无法查询或过细难以抽取维护。","evidence":"关系类型越多，图是否越有知识"},"inputOutput":{"answer":"输入真实问题和建模规则，输出最小可用 schema。","evidence":"输出能支持目标查询的最小 schema"},"mechanism":{"answer":"先从问题反推必要类型关系和身份规则。","evidence":"本体质量看能否稳定回答业务问题"},"interpretation":{"answer":"类型数量多不代表知识质量或查询能力更强。","evidence":"不看类型数量"},"boundary":{"answer":"schema 改变必须迁移旧边并保持语义兼容。","evidence":"必须迁移旧边并保持语义兼容"}},{"section":5,"definition":{"answer":"知识图谱证据闭环从原文抽取图，再由路径回到原文。","evidence":"原创图：从原文证据到图路径，再回到原文"},"problem":{"answer":"它解释 GraphRAG 为何不能只把边列表交给模型。","evidence":"为什么仍不能只把边列表交给模型"},"inputOutput":{"answer":"输入原始文档，输出证据图、查询路径和原文证据。","evidence":"输出实体解析、关系时间来源绑定后的图"},"mechanism":{"answer":"构建时绑定跨度，查询后按路径重新取回对应原文。","evidence":"再由查询路径回取原文"},"interpretation":{"answer":"图负责寻路聚合，原文负责事实核验和纠错。","evidence":"原文跨度负责事实核验与纠错"},"boundary":{"answer":"回答的每条路径都必须回到有权限的原文。","evidence":"必须能回到可访问的原文证据"}},{"section":6,"definition":{"answer":"时态图分别记录事实有效时间和系统获知时间。","evidence":"时间与冲突必须一等建模"},"problem":{"answer":"它处理 CEO 等关系变化时保留历史和来源冲突。","evidence":"CEO 从甲变成乙，为什么不能覆盖旧边"},"inputOutput":{"answer":"输入有效区间获知时间和冲突，输出可按时间查询的并存边。","evidence":"输出可按时间点查询的并存边"},"mechanism":{"answer":"新事实关闭旧有效区间但保留历史来源和冲突状态。","evidence":"关闭旧边有效期而不删除历史证据"},"interpretation":{"answer":"observedAt 表示获知时间，不等于事实生效时间。","evidence":"observedAt 不等于事实生效时间"},"boundary":{"answer":"未解决冲突必须展示或按明确用途规则选择。","evidence":"不能静默覆盖"}},{"section":7,"definition":{"answer":"GraphRAG 按问题尺度检索路径、邻域或社区摘要。","evidence":"GraphRAG 有路径、邻域与社区三个尺度"},"problem":{"answer":"它决定应取有限关系路径还是全局图主题。","evidence":"应取最短路径还是整张图摘要"},"inputOutput":{"answer":"输入问题锚点和预算，输出图结构结果及对应原文。","evidence":"输出受约束路径、有限邻域或社区摘要及对应原文"},"mechanism":{"answer":"实体题扩邻域，多跳题搜路径，全局题用社区。","evidence":"实体题扩邻域，多跳题搜类型路径"},"interpretation":{"answer":"社区摘要只是有损索引而不是最终事实证据。","evidence":"社区摘要是有损索引"},"boundary":{"answer":"必须限制跳数节点和边类型以防枢纽淹没证据。","evidence":"必须限制规模"}},{"section":8,"definition":{"answer":"图与向量检索组合语义锚点、关系约束和文本回查。","evidence":"图与向量检索应互补而非二选一"},"problem":{"answer":"它解决问题无精确实体名时图查询缺少起点的问题。","evidence":"问题里没有精确实体名，图从哪里开始走"},"inputOutput":{"answer":"输入自然语言图和文本，输出路径约束后的候选证据。","evidence":"输出经过实体解析、路径约束和文本重排的候选证据"},"mechanism":{"answer":"向量找锚点，图扩路径，文本重排并回查。","evidence":"向量负责没有精确实体名时找锚点"},"interpretation":{"answer":"各检索通道贡献必须保留以便诊断收益。","evidence":"各路贡献必须可观测"},"boundary":{"answer":"只能在相同质量延迟成本预算下比较方案。","evidence":"同一质量、延迟和成本预算下比较"}},{"section":9,"definition":{"answer":"图评测分解构建、路径查询和最终应用三层质量。","evidence":"评测要分解构建质量与任务贡献"},"problem":{"answer":"它防止问答偶然正确被误当成所有图边都正确。","evidence":"问答答对了，能证明图里的边都对吗"},"inputOutput":{"answer":"输入金标图和任务，输出三层指标与切片结果。","evidence":"输出构建层、查询层和应用层指标"},"mechanism":{"answer":"分别测实体关系时间来源、路径证据和最终答案。","evidence":"输入金标实体、关系、时间、来源、查询路径和最终答案"},"interpretation":{"answer":"平均边准确率会掩盖高连接实体误合并的放大伤害。","evidence":"会掩盖非线性伤害"},"boundary":{"answer":"必须按路径长度热度时间更新和冲突切片。","evidence":"必须按路径长度、实体热度、时间更新和冲突切片"}},{"section":11,"definition":{"answer":"知识图谱、图数据库、网络图和 GraphRAG 属于不同系统层。","evidence":"先澄清：知识图谱、图数据库与可视化不是同义词"},"problem":{"answer":"它避免把能画图或能沿边查询误认为已获得可靠知识。","evidence":"把 CSV 导入图数据库并画成网络，就获得知识图谱了吗"},"inputOutput":{"answer":"输入图类系统，输出存储、展示、知识或检索层分类。","evidence":"输出“图数据库、可视化、知识图谱或图辅助检索”的层级分类"},"mechanism":{"answer":"按是否只存储、只展示、治理事实或辅助检索区分。","evidence":"图数据库负责存储查询，网络图负责展示"},"interpretation":{"answer":"能沿边查询只说明结构存在，不说明边是真实知识。","evidence":"不证明边是真实知识"},"boundary":{"answer":"小型知识图谱也可存在关系表而无需专用图数据库。","evidence":"不强制使用专用图数据库"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分实体、关系、事件与文档片段；手工完成实体解析和路径查询；设计带时间与来源的事实模型；评测图构建误差和端到端问答。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>图解决的是关系寻址，而不只是相似搜索<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">向量检索能找到相关段落，为什么还要图？</p><p>向量空间擅长找“语义像什么”，图擅长问“谁通过什么关系连接到谁”。当任务需要唯一身份、多跳约束、依赖传播、时间版本或全局群落时，显式边使查询可解释；普通 FAQ 或单段即可回答的问题，图的构建维护成本往往不划算。</p><p>知识图谱输入有稳定身份的实体、受控关系、时间和原文证据，输出可按关系和约束查询的事实图。它擅长唯一身份、多跳、时间版本与全局结构，不只是找语义相近文本；路径存在表示图中有连接，不表示连接真实。单段即可回答或维护成本高于收益时不必建图。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>事实应是带限定条件的边<span class=\"dd-badge math\">数据模型</span></h2><p class=\"dd-lead\">“Alice 就职于 Acme”为什么不是三个字符串就够？</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"带限定条件的知识图谱事实\"><mi>Fact</mi><mo>=</mo><mo>(</mo><mi>subject</mi><mo>,</mo><mi>predicate</mi><mo>,</mo><mi>object</mi><mo>,</mo><mi>validTime</mi><mo>,</mo><mi>source</mi><mo>,</mo><mi>confidence</mi><mo>,</mo><mi>status</mi><mo>)</mo></math></div><p>subject/object 使用稳定 ID，显示名称只是属性；predicate 来自受控本体；有效时间说明何时成立；来源指向原文跨度；status 区分候选、确认、冲突与撤回。事件可建成节点，以承载参与者、地点和时间等多元关系，避免把复杂事实硬塞进一条边。</p><p>事实建模输入主体 subject、关系 predicate、客体 object、有效时间 validTime、来源 source、置信度 confidence 和状态 status，输出一条可追踪、可撤回的限定边 Fact。稳定 ID 区分同名实体，本体限制关系含义，时间和来源限定事实何时及为何成立；缺少这些字段的三元组不能支持可靠历史与冲突查询。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：从四句话解析同名实体并回答多跳问题<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">“Apple 收购 Beats；Tim 领导 Apple；Beats 创始人是 Dre”怎样回答“Tim 间接关联谁”？</p><p>先给 Apple 公司分配 <code>org:apple</code>，不能与水果 <code>food:apple</code> 合并；Tim Cook 解析为 <code>person:cook</code>，Dr. Dre 为 <code>person:dre</code>。抽取三条带来源的边：</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"多跳路径的独立近似置信度\"><mi>Ppath</mi><mo>≈</mo><mi>pEntity</mi><mo>×</mo><msup><mi>pEdge</mi><mi>h</mi></msup><mo>=</mo><mn>0.9</mn><mo>×</mo><msup><mn>0.95</mn><mn>3</mn></msup><mo>≈</mo><mn>0.772</mn></math></div><p>查询从 cook 走 <code>leads/acquired/founded_by</code> 的反向边得到 dre，并返回三段原文。若“Apple”解析准确率0.9、三条边各自正确率0.95，粗略独立近似下整条路径可信度为 0.9×0.95³≈<b>0.772</b>；路径越长，错误相乘越明显，实际相关误差会使这个估计更不可靠。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阶段</th><th>候选错误</th><th>后果</th></tr></thead><tbody><tr><td>实体解析</td><td>Apple→水果</td><td>路径完全断裂/误连</td></tr><tr><td>关系抽取</td><td>收购→合作</td><td>语义结论改变</td></tr><tr><td>方向</td><td>founded_by反向</td><td>查询返回错误主体</td></tr><tr><td>来源</td><td>引用邻近句</td><td>路径看似合理但不可证</td></tr></tbody></table></div><p>多跳案例输入实体解析正确率 pEntity、每条边正确率 pEdge 和路径边数 h，输出 cook 到 dre 的可追踪路径及独立近似置信度 Ppath。Ppath=pEntity×pEdge^h；0.9×0.95^3≈0.772 说明每跳误差会累积。独立假设只是粗略直觉，真实实体和关系错误常相关，最终必须回查三段原文。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>本体是问题驱动的约束，不是世界百科全书<span class=\"dd-badge eng\">建模</span></h2><p class=\"dd-lead\">关系类型越多，图是否越有知识？</p><p>先收集真实问题和决策，再定义最小实体类型、关系、方向、基数与时间规则。过宽的 <code>related_to</code> 无法支持精确查询；过细本体又使抽取稀疏、标注困难。每次 schema 变化要有迁移与兼容策略，不能让旧边悄悄改变含义。</p><p>身份规则必须明确：同名不等于同实体，别名也不等于不同实体。使用规范 ID、外部标识符、属性证据和人工复核处理高影响合并。</p><p>本体设计输入真实问题、实体类型、关系方向、基数、时间规则和身份证据，输出能支持目标查询的最小 schema。过宽 relatedTo 无法精确推理，过细关系又难标注和维护；本体质量看能否稳定回答业务问题，不看类型数量。schema 变化必须迁移旧边并保持语义兼容。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：从原文证据到图路径，再回到原文<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">GraphRAG 为什么仍不能只把边列表交给模型？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 310\" role=\"img\" aria-label=\"文档块经过实体解析关系抽取和来源绑定进入时态图，再经路径社区和文本混合检索回答\"><defs><marker id=\"k27a\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"18\" y=\"105\" width=\"120\" height=\"90\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"78\" y=\"134\" text-anchor=\"middle\" class=\"svg-t\">原始文档</text><text x=\"78\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">版本 · 页码</text><text x=\"78\" y=\"179\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">字符跨度</text><path d=\"M138,150 L190,150\" stroke=\"#788293\" marker-end=\"url(#k27a)\"/><rect x=\"195\" y=\"75\" width=\"165\" height=\"150\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"277\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\">构建管线</text><text x=\"277\" y=\"133\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">实体解析 / 去重</text><text x=\"277\" y=\"157\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">关系 + 时间抽取</text><text x=\"277\" y=\"181\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">来源与置信绑定</text><text x=\"277\" y=\"205\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">人工抽检 / 撤回</text><path d=\"M360,150 L412,150\" stroke=\"#788293\" marker-end=\"url(#k27a)\"/><rect x=\"417\" y=\"75\" width=\"135\" height=\"150\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><circle cx=\"455\" cy=\"126\" r=\"15\" fill=\"#303746\" stroke=\"#8b76bd\"/><circle cx=\"512\" cy=\"112\" r=\"15\" fill=\"#303746\" stroke=\"#8b76bd\"/><circle cx=\"492\" cy=\"181\" r=\"15\" fill=\"#303746\" stroke=\"#8b76bd\"/><line x1=\"468\" y1=\"121\" x2=\"497\" y2=\"116\" stroke=\"#788293\"/><line x1=\"507\" y1=\"127\" x2=\"497\" y2=\"166\" stroke=\"#788293\"/><line x1=\"464\" y1=\"139\" x2=\"482\" y2=\"168\" stroke=\"#788293\"/><text x=\"484\" y=\"211\" text-anchor=\"middle\" class=\"svg-t\">时态证据图</text><path d=\"M552,150 L600,150\" stroke=\"#788293\" marker-end=\"url(#k27a)\"/><rect x=\"605\" y=\"75\" width=\"112\" height=\"150\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"661\" y=\"107\" text-anchor=\"middle\" class=\"svg-t\">查询</text><text x=\"661\" y=\"135\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">路径 / 邻域</text><text x=\"661\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">社区摘要</text><text x=\"661\" y=\"181\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">原文重取</text><text x=\"661\" y=\"205\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">带证据回答</text><path d=\"M661,225 C661,280 78,280 78,195\" fill=\"none\" stroke=\"#cf7c72\" stroke-dasharray=\"6 5\" marker-end=\"url(#k27a)\"/><text x=\"367\" y=\"292\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">回答中的每条路径都必须回到原文核验</text></svg><figcaption>图 1　图用于寻路与聚合；原始跨度仍是事实证据和纠错入口。</figcaption></figure><p>证据闭环输入原始文档与版本，输出实体解析、关系时间来源绑定后的图，再由查询路径回取原文。图用于寻路和聚合，原文跨度负责事实核验与纠错；只把边列表交给模型会丢失限定条件和抽取不确定性。每条回答路径都必须能回到可访问的原文证据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>时间与冲突必须一等建模<span class=\"dd-badge eng\">时态</span></h2><p class=\"dd-lead\">CEO 从甲变成乙，为什么不能覆盖旧边？</p><p>用 <code>valid_from/valid_to</code> 表示事实有效期，用 observed_at 表示系统何时获知；两者不同。新证据可以关闭旧边的有效区间，但不能删除历史来源。来自不同来源且时间重叠的冲突边应并存并标状态，查询时按时间、来源权威和用途选择或向用户展示冲突。</p><p>时态建模输入事实有效区间 validFrom/validTo、系统获知时间 observedAt、来源权威和冲突状态，输出可按时间点查询的并存边。新任 CEO 出现时关闭旧边有效期而不删除历史证据；observedAt 不等于事实生效时间。来源冲突未解决时必须展示或按明确用途规则选择，不能静默覆盖。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>GraphRAG 有路径、邻域与社区三个尺度<span class=\"dd-badge eng\">检索</span></h2><p class=\"dd-lead\">一个问题应取最短路径还是整张图摘要？</p><p>实体问题可从锚点扩展有限跳邻域；多跳关系题寻找受类型约束的路径；全局主题题可使用社区检测与分层摘要。每种扩展都要限制跳数、节点数和边类型，否则高连接枢纽会淹没相关证据。</p><p>社区摘要是二次生成的有损索引，不能当最终证据。回答前重新取回路径对应原文，并与向量/关键词结果融合，处理图中尚未结构化的新事实。</p><p>GraphRAG 检索输入问题类型、锚点实体和跳数节点预算，输出受约束路径、有限邻域或社区摘要及对应原文。实体题扩邻域，多跳题搜类型路径，全局主题题用社区；社区摘要是有损索引，不能作为最终证据。枢纽节点和无限扩展会淹没相关内容，必须限制规模。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>图与向量检索应互补而非二选一<span class=\"dd-badge eng\">混合系统</span></h2><p class=\"dd-lead\">问题里没有精确实体名，图从哪里开始走？</p><p>向量检索可找候选文本和实体，实体解析后进入图；图路径给出结构约束，再用文本重排选择证据。也可将图邻域文本化后嵌入。关键是保留各路召回来源，评测“向量-only、图-only、混合”在同一预算下的质量、延迟与成本。</p><p>图向量混合输入自然语言问题、向量候选实体、图结构和文本证据，输出经过实体解析、路径约束和文本重排的候选证据。向量负责没有精确实体名时找锚点，图负责关系约束，文本负责回查；各路贡献必须可观测。图与向量只能在同一质量、延迟和成本预算下比较。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要分解构建质量与任务贡献<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">问答答对了，能证明图里的边都对吗？</p><p>构建层分别测实体识别、实体链接、关系类型/方向、时间和来源跨度的精确率与召回率；查询层测锚点命中、路径召回、证据正确性和延迟；应用层测端到端答案、引用完整性与相对混合检索的增益。</p><p>按路径长度、实体热度、时间更新与冲突切片。对误合并做专项指标，因为一个高连接实体的错误会污染大量路径，平均边准确率会掩盖这种非线性伤害。</p><p>图评测输入金标实体、关系、时间、来源、查询路径和最终答案，输出构建层、查询层和应用层指标。问答偶然答对不能证明所有边正确；高连接实体误合并会污染大量路径，平均边准确率会掩盖非线性伤害。必须按路径长度、实体热度、时间更新和冲突切片。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">漂亮的图不等于可靠的知识。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>节点越多知识越多</td><td>身份、边语义和证据质量更关键</td></tr><tr><td>LLM抽取后即可入库</td><td>需实体解析、时间、来源和抽检</td></tr><tr><td>最短路径就是答案</td><td>路径仍可能语义不成立或边错误</td></tr><tr><td>GraphRAG替代向量检索</td><td>结构与语义召回应做预算内比较</td></tr><tr><td>社区摘要可作证据</td><td>摘要有损，最终需回到原文</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>数据库、信息抽取、检索与实体识别</td></tr><tr><td><b>本页核心</b></td><td>本体、实体解析、时态边、路径查询</td></tr><tr><td>相邻</td><td>RAG、重排、引用、Agent记忆</td></tr><tr><td>工程</td><td>版本迁移、冲突、撤回与增量更新</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>先澄清：知识图谱、图数据库与可视化不是同义词<span class=\"dd-badge intuition\">概念消歧</span></h2><p class=\"dd-lead\">把 CSV 导入图数据库并画成网络，就获得知识图谱了吗？</p><p>图数据库是一种存储与查询技术，可保存任意节点和边；网络图只是视觉呈现；知识图谱还要求稳定实体身份、明确关系语义、时间、来源和治理。反过来，小型知识图谱也可以存在关系表中，不一定需要专用图数据库。GraphRAG 则是使用图索引辅助检索/生成的系统模式，不等于图本身。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>“能沿边查询”只证明结构存在，不证明边表达真实知识；先核验身份、关系方向和证据跨度。</div><p>概念辨析输入一个图存储、网络可视化或 GraphRAG 系统，输出“图数据库、可视化、知识图谱或图辅助检索”的层级分类。图数据库负责存储查询，网络图负责展示，知识图谱还要求身份关系时间来源治理，GraphRAG 使用图帮助检索生成；能沿边查询不证明边是真实知识。小图也可存在关系表中，不强制使用专用图数据库。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>从真实多跳问题定义最小本体</li><li>抽取候选实体与关系</li><li>解析身份并绑定原文跨度</li><li>写入带时间版本的边</li><li>以实体或文本召回建立锚点</li><li>受约束扩展路径/邻域/社区</li><li>重取原文并生成引用回答</li><li>用纠错与新证据更新图</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>实体名称为什么不能直接当 ID？</li><li>多跳路径为何越长越脆弱？</li><li>valid_time 与 observed_at 的区别？</li><li>社区摘要为何不能当最终证据？</li><li>如何证明图值得维护？</li><li>假设“知识图谱：把身份、关系、时间与证据组织成可查询事实”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>同名可指不同实体，别名也可指同一实体，需要稳定身份与解析证据。</li><li>每一跳都可能有实体或关系误差，错误会累积并传播。</li><li>前者是事实何时成立，后者是系统何时获知。</li><li>它是有损生成索引，必须回到对应原文跨度核验。</li><li>与同预算向量和混合基线比较端到端任务、证据、延迟和维护成本。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2003.02320\" target=\"_blank\" rel=\"noopener\">Knowledge Graphs Survey</a>：知识图谱表示、构建与应用综述</li><li><a href=\"https://arxiv.org/abs/2404.16130\" target=\"_blank\" rel=\"noopener\">From Local to Global: GraphRAG</a>：图索引与社区摘要</li><li><a href=\"https://arxiv.org/abs/2405.14831\" target=\"_blank\" rel=\"noopener\">HippoRAG</a>：知识图上的长期检索</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
